from newspaper import Article
from gensim.summarization.summarizer import summarize

def sumary(text):
    sum_list=summarize(text, word_count=100, split=True)
    sum=''
    for i in sum_list:
        if(len(i.split())>4):
            sum=sum+'‣ '+str(i)+'<br>'
    return sum

